#Integer data type 
age = 25 
print("Age (Integer):", age)

#Float data type 
height = 5.7 
print("Height (Float):", height)

# String data type 
name = "Thala" 
print("Name (String):", name)

# List data type 
fruits = ["Apple", "Banana", "Cherry"] 
print("Fruits (List):", fruits)

#Tuple data type 
coordinates = (10.2, 30.9) 
print("Coordinates (Tuple):", coordinates)

#Dictionary data type 
person = {"name": "Rudra", "age": 25} 
print("Person (Dictionary):", person)

# Set data type 
colors = {"Red", "Green", "Blue"}
print("Colors (Set):", colors)

#Boolean data type

is_adult = True 
print("Is Adult (Boolean):", is_adult)